import sys
M = 1000000007
P = 2 * (M + 1)  # Pisano period for p=1 or 4 mod 5 divides p-1; use 2(p+1) for +-2 mod 5
# 1e9+7 mod 5 = 2 -> period divides 2(p+1)
def fib(n):
    a, b = 0, 1
    for c in bin(n)[2:]:
        t = a * ((2 * b - a) % M) % M
        u = (a * a + b * b) % M
        if c == '1':
            a, b = u, (t + u) % M
        else:
            a, b = t, u
    return a
def main():
    out = []
    cache = {}
    for l in sys.stdin.read().split():
        n = int(l) % P
        r = cache.get(n)
        if r is None:
            r = cache[n] = fib(n)
        out.append(r)
    sys.stdout.write("\n".join(map(str, out)) + "\n")
main()
